/* bcmfw/jpeg/env/bcm: the libc the decoder uses, on the BCM (vc4-elf-gcc
 * has none); bcmfw/lib/string.c and bcmfw/jpeg/files.c define them */
#ifndef JENV_BCM_STRING_H
#define JENV_BCM_STRING_H
#include <stddef.h>
void *memcpy(void *dst, const void *src, size_t n);
void *memset(void *dst, int c, size_t n);
void *memmove(void *dst, const void *src, size_t n);
int memcmp(const void *a, const void *b, size_t n);
#endif
